function parseCsvLine(line){
  const values = [];
  let current = '';
  let inQuotes = false;
  let closedQuote = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"';
        i++;
      } else if (inQuotes) {
        inQuotes = false;
        closedQuote = true;
      } else {
        if (current !== '' || closedQuote) throw new Error('รูปแบบเครื่องหมายคำพูด CSV ไม่ถูกต้อง');
        inQuotes = true;
      }
    } else if (ch === ',' && !inQuotes) {
      values.push(current);
      current = '';
      closedQuote = false;
    } else {
      if (closedQuote) throw new Error('พบข้อมูลหลังเครื่องหมายคำพูดปิด CSV');
      current += ch;
    }
  }
  if (inQuotes) throw new Error('เครื่องหมายคำพูด CSV ปิดไม่ครบ');
  values.push(current);
  return values;
}

function parseCsv(text){
  const lines = text.replace(/^\uFEFF/, '').split(/\r?\n/).filter(line => line.trim() !== '');
  if (!lines.length) return [];
  const headers = parseCsvLine(lines[0]).map(h => h.trim());
  if (headers.some(h => !h) || new Set(headers).size !== headers.length) {
    throw new Error('หัวคอลัมน์ CSV ว่างหรือซ้ำ');
  }
  return lines.slice(1).map(line => {
    const cols = parseCsvLine(line);
    if (cols.length !== headers.length) throw new Error('จำนวนคอลัมน์ CSV ไม่ครบตามหัวตาราง');
    return headers.reduce((acc, header, idx) => {
      acc[header] = cols[idx];
      return acc;
    }, {});
  });
}
